from __future__ import annotations

from pathlib import Path
import json
from typing import Any

import joblib
import numpy as np
import pandas as pd
from catboost import CatBoostClassifier, Pool

ROOT = Path(__file__).resolve().parents[1]
DATA = ROOT / "data"
MODEL_DIR = ROOT / "model"

# Fields that can be generated by a return/service workflow. These are excluded
# from any pre-dispatch model even when they are present in historical rows.
LEAKAGE_COLUMNS = ["pickup_scheduled_at", "last_service_event_type"]
RAW_DROP = [
    "order_id",
    "returned",
    "order_placed_at",
    "signup_date",
    "launch_date",
    "pickup_scheduled_at",
    "last_service_event_type",
    "delivery_note",
]

